import { spawnSync } from 'node:child_process'
import { DatabaseSync } from 'node:sqlite'
import { mkdirSync, writeFileSync, readFileSync } from 'node:fs'
import path from 'node:path'
import assert from 'node:assert/strict'
const source = path.resolve(import.meta.dirname, '..')
const bundle = path.resolve(process.argv[2] ?? path.join(source, '../Deployment/seed/catalogue-metadata.json'))
const directory = path.join(source, '.test-instance', 'bundle-validation-' + Date.now())
mkdirSync(directory, { recursive: true })
const database = path.join(directory, 'database.sqlite3')
const cli = path.join(source, 'scripts/catalogue-bundle.mjs')
function run (target = database, mode = '--isolated-test') {
  return spawnSync(process.execPath, [cli, 'import', '--database', target, '--bundle', bundle, mode], { encoding: 'utf8', cwd: source })
}
const expected = JSON.parse(readFileSync(bundle, 'utf8'))
const checks = []
const first = run()
assert.equal(first.status, 0, first.stderr)
assert.equal(JSON.parse(first.stdout.trim()).added, expected.entries.length)
checks.push('fresh isolated database imports every metadata entry')
let db = new DatabaseSync(database)
for (const table of ['users', 'paths', 'songs', 'media', 'queue', 'providers']) assert.equal(db.prepare(`SELECT COUNT(*) AS n FROM ${table}`).get().n, 0, table)
assert.equal(db.prepare('SELECT COUNT(*) AS n FROM catalogueEntries').get().n, expected.entries.length)
assert.equal(db.prepare('SELECT COUNT(*) AS n FROM catalogueSuggestions').get().n, expected.entries.filter(e => e.suggestion).length)
assert.equal(db.prepare('SELECT COUNT(*) AS n FROM catalogueSources').get().n, expected.entries.reduce((n, e) => n + e.sources.length, 0))
checks.push('no users, accounts, playable media, paths, queues or providers are copied')
const row = db.prepare('SELECT entryId FROM catalogueEntries ORDER BY entryId LIMIT 1').get()
const manual = JSON.stringify({ approved: { genre: '', language: '', decade: '', performance: '', collections: [] }, discoveryFeatured: true })
db.prepare("UPDATE catalogueEntries SET data=?,state='approved' WHERE entryId=?").run(manual, row.entryId)
db.close()
const second = run()
assert.equal(second.status, 0, second.stderr)
assert.equal(JSON.parse(second.stdout.trim()).added, 0)
assert.equal(JSON.parse(second.stdout.trim()).suggestions, 0)
db = new DatabaseSync(database)
assert.equal(db.prepare('SELECT data FROM catalogueEntries WHERE entryId=?').get(row.entryId).data, manual)
db.close()
checks.push('repeat import adds no duplicates and preserves host decisions including blanks')
const refusal = path.join(directory, 'unmarked.sqlite3')
db = new DatabaseSync(refusal)
db.exec("CREATE TABLE prefs(key TEXT,data TEXT); INSERT INTO prefs VALUES ('sentry','keep')")
db.close()
const rejected = run(refusal)
assert.notEqual(rejected.status, 0)
assert.match(rejected.stderr, /Refusing an existing database/)
db = new DatabaseSync(refusal)
assert.equal(db.prepare('SELECT COUNT(*) AS n FROM sqlite_master WHERE type=\'table\'').get().n, 1)
assert.equal(db.prepare('SELECT data FROM prefs').get().data, 'keep')
db.close()
checks.push('an existing unmarked database is refused before migrations or metadata writes')
const production = path.join(directory, 'production.sqlite3')
const productionFirst = run(production, '--fresh-instance')
assert.equal(productionFirst.status, 0, productionFirst.stderr)
assert.equal(JSON.parse(productionFirst.stdout.trim()).added, expected.entries.length)
db = new DatabaseSync(production)
assert.equal(db.prepare("SELECT data FROM prefs WHERE key='modernManagedInstance'").get().data, 'true')
assert.equal(db.prepare("SELECT data FROM prefs WHERE key='modernTestInstance'").get(), undefined)
assert.equal(db.prepare('PRAGMA quick_check').get().quick_check, 'ok')
assert.equal(db.prepare('PRAGMA foreign_key_check').all().length, 0)
db.close()
checks.push('production imports the full catalogue with a persistent production marker and no test banner marker')
const productionAgain = run(production, '--fresh-instance')
assert.equal(productionAgain.status, 0, productionAgain.stderr)
assert.equal(JSON.parse(productionAgain.stdout.trim()).added, 0)
checks.push('repeat production import is idempotent')
for (const [target, mode] of [[production, '--isolated-test'], [database, '--fresh-instance'], [refusal, '--fresh-instance']]) {
  const result = run(target, mode)
  assert.notEqual(result.status, 0)
  assert.match(result.stderr, /Refusing an existing database/)
}
checks.push('production and QA databases cannot be cross-imported, and an unmarked production database is refused')
const report = { bundle, entries: expected.entries.length, suggestions: expected.entries.filter(e => e.suggestion).length, checks, database, checkedAt: new Date().toISOString() }
mkdirSync(path.join(source, 'qa-artifacts'), { recursive: true })
writeFileSync(path.join(source, 'qa-artifacts/bundle-checks.json'), JSON.stringify(report, null, 2))
for (const check of checks) console.log('PASS:', check)
